import math


def r(x):
    # For the sigmoid-like surrogate, mapping x to 1 - x targets the symmetric point
    # across the center of the sigmoid, where the outputs should sum to approximately 1.0.
    return 1.0 - float(x)


def R(y_orig, y_new):
    # Conservation invariant: y_orig + y_new ≈ 1.0
    # We use a robust tolerance of 0.08 to account for neural network approximation errors.
    return math.isclose(y_orig + y_new, 1.0, abs_tol=0.08)
